const STATUS_GLYPH: Record<string, string> = { running: '●', done: '✓', failed: '✗', planned: '◷' }

// Opens the agents pane, or closes it when it is up; true when it ends up open.
async function togglePane($: EngineInterface): Promise<boolean> {
  const isOpen = (await $.ui.panes()).some(p => p.id === PANE)
  if (isOpen) {
    await $.ui.close({ id: PANE })
    return false
  }
  const at = await $.clock.now()
  await update($, now, () => at)
  await $.ui.open({ id: PANE, title: tr().pane })
  return true
}

async function autoOpen($: EngineInterface, key: string): Promise<void> {
  const p = await read($, panel)
  if (p.autoOpenedFor === key) return
  await update($, panel, prev => ({ ...prev, autoOpenedFor: key }))
  void $.ui.open({ id: PANE, title: tr().pane })
}

// Session start, after the other hooks: the language, the tools and the clock.
// The mod's register.tsx calls it (one session.start hook for the whole mod).
async function progressStart($: EngineInterface, options: Parameters<Register>[1]): Promise<void> {
  lang = await detectLang($, options.language)
  await loadPortraits($)
  await $.tool.register({
    name: 'progress',
    description:
      'Report /savvy-flow progress to the progress bar above the prompt and the agents panel. ' +
      'Call it after presenting the plan (title, total, tasks, phase "delegate"), each time a task is accepted (done), ' +
      'when switching phase or re-planning (tasks), and once at the end with finished: true. Fields left out keep their previous value. ' +
      'Optional for any long job: `groups` splits the bar into named stretches (one per stage) with their steps, and the bar and the agents panel then show the step in progress.',
    inputSchema: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Short name of the overall task, a few words.' },
        total: { type: 'integer', minimum: 0, description: 'Number of planned worker tasks.' },
        done: { type: 'integer', minimum: 0, description: 'Number of tasks accepted after review.' },
        phase: { type: 'string', enum: [...PHASES] },
        finished: { type: 'boolean', description: 'True once the flow is closed.' },
        step: { type: 'string', description: 'The step in progress, a few words; shown on the bar. Not needed with `groups`, which name it from `done`.' },
        groups: {
          type: 'array',
          description:
            'Named stretches of the bar, in order, each with its steps in order. The total is the number of steps unless `total` is given; `done` counts steps across all groups.',
          items: {
            type: 'object',
            properties: {
              name: { type: 'string', description: 'A word or two, shown under its stretch of the bar.' },
              steps: {
                type: 'array',
                description: 'The steps of this stretch, in order: a few words each, or { name, short } to give the bar a shorter name than the panel.',
                items: {
                  anyOf: [
                    { type: 'string' },
                    { type: 'object', properties: { name: { type: 'string' }, short: { type: 'string', description: 'One word or two, for the bar.' } }, required: ['name'] },
                  ],
                },
              },
            },
            required: ['name', 'steps'],
          },
        },
        tasks: {
          type: 'array',
          description:
            'The planned worker tasks in order, numbered from 1. Each title must equal the Agent tool `description` the task will be delegated with, so the panel can match runs to tasks.',
          items: {
            type: 'object',
            properties: {
              title: { type: 'string', description: 'A few words; reused verbatim as the Agent description.' },
              tier: { type: 'string', enum: ['fable', 'heavy', 'careful', 'medium', 'light'] },
              after: { type: 'array', items: { type: 'integer' }, description: 'Numbers of the tasks this one waits for.' },
            },
            required: ['title', 'tier'],
          },
        },
      },
    },
  })
  await $.tool.register({
    name: 'step',
    description:
      'For savvy-flow workers: report progress on your own task to the agents panel. ' +
      'Right after reading the brief, call it with `total` (your plan in 3-8 steps) and `done: 0`; ' +
      'call it again as each step finishes. Cheap and silent: it only draws a bar.',
    inputSchema: {
      type: 'object',
      properties: {
        done: { type: 'integer', minimum: 0, description: 'Steps finished so far.' },
        total: { type: 'integer', minimum: 1, description: 'Steps planned; may change if the plan changes.' },
        note: { type: 'string', description: 'The step in progress, a few words.' },
      },
      required: ['done'],
    },
  })
  await $.command.register({
    name: 'agents-info',
    description: 'Show or hide the panel of subagents: running, finished and planned, with model, context, cost and time',
  })

  // A chat reopened (the app restarted, the computer slept) finds its bar as it left it.
  const kept = await keptBar($)
  if (kept?.flow && !kept.flow.isFinished && !(await read($, flow))) await update($, flow, () => kept.flow)

  // The agents pane stays open, like the file tree: empty until a subagent runs.
  if (!(await $.ui.panes()).some(p => p.id === PANE)) void $.ui.open({ id: PANE, title: tr().pane })

  // Ticks the running agents' clocks and the main turn's; quiet when nothing runs.
  $.clock.every(1000, () => {
    void (async () => {
      const list = await read($, agents)
      const turn = await read($, turnA)
      if (!list.some(a => a.status === 'running') && !(turn && turn.endedAt === undefined)) return
      const at = await $.clock.now()
      await update($, now, () => at)
    })()
  })
}

// A subagent's response landed: its model, context, tokens and cost.
async function progressAfterStep(
  $: EngineInterface,
  e: { agentId?: string; effort?: unknown; model: string },
  result: TurnStepResult,
): Promise<void> {
  const agentId = e.agentId
  const usage = result.usage
  if (!agentId || !usage) return

  const model = usage.model || e.model
  await update($, agents, list =>
    list.map((a): AgentRun =>
      a.agentId !== agentId
        ? a
        : {
            ...a,
            model,
            effort: typeof e.effort === 'string' ? e.effort : a.effort,
            status: 'running',
            endedAt: undefined,
            contextTokens:
              (usage.input_tokens || 0) +
              (usage.cache_read_input_tokens || 0) +
              (usage.cache_creation_input_tokens || 0) +
              (usage.output_tokens || 0),
            contextMax: windowOf(model),
            tokens:
              a.tokens +
              (usage.input_tokens || 0) +
              (usage.output_tokens || 0) +
              (usage.cache_read_input_tokens || 0) +
              (usage.cache_creation_input_tokens || 0),
            costUsd: a.costUsd + costOf(model, usage),
            steps: a.steps + 1,
          },
    ),
  )
}

// A bar drawn from Claude's own list leaves this long after it reached 100%.
const AUTO_CLEAR_MS = 10_000

// Every change to the bar goes through here: a step forward on the same bar
// remembers where the tag was (its glide), and reaching 100% starts the crab's
// celebration and a chime; a bar from Claude's own list then leaves on its own.
async function setFlow($: EngineInterface, change: (prev: Flow | null) => Flow | null): Promise<Flow | null> {
  const at = await $.clock.now()
  const hit: { done: Flow | null } = { done: null }
  const next = await update($, flow, p => {
    const n = change(p)
    if (!n || n === p) return n
    const same = !!p && !p.isFinished && p.title === n.title && (p.source ?? 'tool') === (n.source ?? 'tool')
    let out = n
    if (same && p && ratio(n) !== ratio(p)) out = { ...out, moved: { from: ratio(p) * 100, at } }
    if (n.isFinished && !(p?.isFinished && p.title === n.title)) {
      out = { ...out, doneAt: at }
      hit.done = out
    }
    return out
  })
  const done = hit.done
  if (done) {
    await chime($, 'finish')
    if (done.source === 'todo' || done.source === 'plan') {
      $.clock.after(AUTO_CLEAR_MS, () => void update($, flow, f => (f && f.isFinished && f.doneAt === done.doneAt ? null : f)))
    }
  }
  return next
}

// A skill's bar (the progress tool) wins over Claude's own list while it runs.
const toolBarOn = (f: Flow | null): boolean => !!f && !f.isFinished && (f.source ?? 'tool') === 'tool'

// Claude's task list, as it now stands: the bar follows it.
async function showList($: EngineInterface, items: TodoItem[]) {
  await setFlow($, p => {
    if (toolBarOn(p)) return p
    if (!items.length) return p && p.source === 'todo' ? null : p
    // The list carries on the plan it came from, and keeps its title while it runs.
    const keep = p && !p.isFinished && (p.source === 'plan' || p.source === 'todo')
    return listFlow(keep && p ? p.title : tr().tasks, items, 'todo')
  })
}

// A plan the person approved: its steps on the bar until a task list takes over.
async function showPlan($: EngineInterface, md: string) {
  const plan = planOf(md)
  if (plan.steps.length < 2) return
  const title = capital(clip(plan.title, 48)) || tr().plan
  await setFlow($, p => (toolBarOn(p) ? p : listFlow(title, plan.steps.map(content => ({ content, status: 'pending' })), 'plan')))
}

// /crabhud demo: twenty seconds of sample data (a bar that walks to 100%, two
// agents, the amber wait, limits when there are none), then everything back
// as it was. What was on screen is kept aside, not lost.
const DEMO_MS = 20_000
const DEMO_STEP_MS = 2_400
let demoKept: { flow: Flow | null; limits: HudLimits | null; hadLimits: boolean } | null = null

const DEMO_TEXT = {
  en: { title: 'crabhud demo', groups: [['Plan', ['Read the code', 'Sketch']], ['Build', ['Bar', 'Rings', 'Panel']], ['Check', ['Tests']]], agents: ['Draw the rings', 'Check the tests'], ask: 'npm test' },
  ru: { title: 'демо crabhud', groups: [['План', ['Читать код', 'Эскиз']], ['Сборка', ['Полоса', 'Кольца', 'Панель']], ['Проверка', ['Тесты']]], agents: ['Нарисовать кольца', 'Проверить тесты'], ask: 'npm test' },
  pt: { title: 'demo do crabhud', groups: [['Planejar', ['Ler o código', 'Esboçar']], ['Fazer', ['Barra', 'Anéis', 'Painel']], ['Conferir', ['Testes']]], agents: ['Desenhar os anéis', 'Conferir os testes'], ask: 'npm test' },
} as const

async function startDemo($: EngineInterface): Promise<void> {
  const at = await $.clock.now()
  if (!demoKept) {
    const limits = await read($, limitsA)
    demoKept = { flow: await read($, flow), limits, hadLimits: !!limits && limits.limits.length > 0 }
  }
  const until = at + DEMO_MS
  await update($, demoA, () => until)
  const D = DEMO_TEXT[lang]
  const groups: StepGroup[] = D.groups.map(([name, steps]) => ({ name, steps: [...steps], short: steps.map(() => '') }))
  const total = groups.reduce((n, g) => n + g.steps.length, 0)
  const bar = (done: number): Flow => ({
    title: D.title,
    total,
    done,
    running: 0,
    phase: done >= total ? 'close' : 'delegate',
    isFinished: done >= total,
    tasks: [],
    step: '',
    groups,
    source: 'tool',
  })
  await update($, flow, () => null)
  await setFlow($, () => bar(0))
  if (!demoKept.hadLimits) {
    const hour = 3600000
    await update($, limitsA, () => ({
      limits: [
        { kind: 'five_hour', percent: 37, resetsAt: at + 2 * hour + 10 * 60000, rate: 12 },
        { kind: 'seven_day', percent: 64, resetsAt: at + 3 * 24 * hour, rate: 0.6 },
      ],
      at: -1,
    }))
  }
  const live = async () => (await read($, demoA)) === until
  for (let done = 1; done <= total; done++) {
    $.clock.after(done * DEMO_STEP_MS, () => void (async () => {
      if (await live()) await setFlow($, () => bar(done))
    })())
  }
  const agent = (i: number, type: string, model: string): AgentRun => ({
    id: `demo-${i}`,
    type,
    description: D.agents[i],
    model,
    status: 'running',
    startedAt: at + 3000,
    contextTokens: 42_000 + i * 31_000,
    contextMax: 200_000,
    tokens: 58_000 + i * 20_000,
    costUsd: 0.38 + i * 0.27,
    steps: 6,
    round: 1,
    stepDone: 1,
    stepTotal: 4,
    stepNote: D.groups[1][1][1 + i] ?? '',
  })
  $.clock.after(3000, () => void (async () => {
    if (!(await live())) return
    const now_ = await $.clock.now()
    await update($, now, () => now_)
    await update($, agents, l => [...l.filter(a => !a.id.startsWith('demo-')), agent(0, 'crabhud:savvy-medium', 'claude-opus-5-5'), agent(1, 'crabhud:savvy-light', 'claude-sonnet-5-5')])
  })())
  $.clock.after(6500, () => void (async () => {
    if (await live()) await update($, agents, l => l.map(a => (a.id.startsWith('demo-') ? { ...a, stepDone: 3 } : a)))
  })())
  // The amber wait, for a few seconds, as when Claude asks to run a command.
  $.clock.after(8000, () => void (async () => {
    if (await live()) await startWaiting($, { kind: 'permission', tool: 'Bash', detail: D.ask, id: 'demo-ask' })
  })())
  $.clock.after(11500, () => void (async () => {
    if (await live()) await update($, waitingA, w => (w?.id === 'demo-ask' ? null : w))
  })())
  $.clock.after(12500, () => void (async () => {
    if (!(await live())) return
    const end = await $.clock.now()
    await update($, agents, l => l.map(a => (a.id.startsWith('demo-') ? { ...a, status: 'done' as const, endedAt: end, stepDone: 4 } : a)))
  })())
  $.clock.after(DEMO_MS, () => void (async () => {
    if (await live()) await stopDemo($)
  })())
}

async function stopDemo($: EngineInterface): Promise<void> {
  await update($, demoA, () => 0)
  await update($, waitingA, w => (w?.id === 'demo-ask' ? null : w))
  await update($, agents, l => l.filter(a => !a.id.startsWith('demo-')))
  const kept = demoKept
  demoKept = null
  if (!kept) return
  // Only what the demo drew goes back: a real bar or reading that came meanwhile stays.
  const title = DEMO_TEXT[lang].title
  await update($, flow, f => (f && f.title === title ? kept.flow : f))
  await update($, limitsA, l => (l && l.at === -1 ? kept.limits : l))
}

// A tool call that ran and answered (no deny, no error).
const answered = (r: { deny?: string; isError?: boolean }): boolean => r.deny === undefined && !r.isError

// The flow's progress, reported to the bar.
// The skill's bar, kept on disk per chat in $.store: the engine's own state
// lives as long as the chat's process, so a chat reopened would lose it, and a
// lone `done` would then draw an empty bar. Recent chats only.
type KeptBar = { flow: Flow | null; at: number }
const KEPT_CHATS = 30
const KEPT_MS = 14 * 24 * 3600000

async function keptBars($: EngineInterface): Promise<Record<string, KeptBar>> {
  const v = (await $.store.get('bars').catch(() => null)) as Record<string, KeptBar> | null
  return v && typeof v === 'object' ? { ...v } : {}
}

async function keptBar($: EngineInterface): Promise<KeptBar | null> {
  const id = await $.session.id().catch(() => '')
  return id ? ((await keptBars($))[id] ?? null) : null
}

// `null` marks a bar the person closed (✕).
async function keepBar($: EngineInterface, f: Flow | null): Promise<void> {
  const id = await $.session.id().catch(() => '')
  if (!id) return
  const at = await $.clock.now()
  const all = await keptBars($)
  all[id] = { flow: f, at }
  const recent = Object.entries(all)
    .filter(([, b]) => at - b.at < KEPT_MS)
    .sort((a, b) => b[1].at - a[1].at)
    .slice(0, KEPT_CHATS)
  await $.store.set('bars', Object.fromEntries(recent)).catch(() => undefined)
}

const NO_BAR =
  'no bar in this chat to move: send `title` and the full `groups` (or `total`) with `done` to draw it again'

async function reportProgress($: EngineInterface, e: ToolCallInput) {
  const input = e as unknown as ProgressInput
  // A bar of Claude's own list gives way to the skill's.
  const own = (p: Flow | null) => (p && (p.source ?? 'tool') !== 'tool' ? null : p)
  let prev = own(await read($, flow))
  const starts = input.title !== undefined || input.total !== undefined || !!input.groups?.length || !!input.tasks?.length
  if (!prev && !starts) {
    // Only a step forward, with no bar on: carry on from the one kept, rather
    // than draw an empty one.
    const kept = await keptBar($)
    if (kept && !kept.flow) return { result: 'ok: the person closed the bar' }
    if (!kept?.flow || kept.flow.isFinished) return { result: NO_BAR }
    prev = kept.flow
    await update($, flow, p => (own(p) ? p : kept.flow))
  }
  if (isNewFlow(prev, input) && input.title !== undefined) {
    // A new flow starts with a clean list; agents still running stay.
    await update($, agents, list => list.filter(a => a.status === 'running'))
  }
  const next = await setFlow($, p => ({ ...merge(own(p), input), source: 'tool' }))
  if (next) await keepBar($, next)
  if (next && input.tasks?.length) await autoOpen($, next.title)
  return { result: `ok: ${label(next ?? blank())}` }
}

// A worker's own progress: the call runs in the worker's loop, so agentId names it.
async function reportStep($: EngineInterface, e: ToolCallInput) {
  const input = e as unknown as { done?: number; total?: number; note?: string }
  const agentId = e.agentId
  if (!agentId) return { result: 'ignored: only subagents report steps' }
  await update($, agents, list =>
    list.map(a => {
      if (a.agentId !== agentId) return a
      const total = Math.max(0, Math.round(input.total ?? a.stepTotal ?? 0))
      const done = Math.max(0, Math.round(input.done ?? a.stepDone ?? 0))
      return { ...a, stepTotal: total, stepDone: total ? Math.min(total, done) : done, stepNote: input.note?.trim() || undefined }
    }),
  )
  return { result: 'ok' }
}

const registerProgress: Register = on => {
  on('command.run', { command: 'agents-info' }, async $ => {
    const isOpen = await togglePane($)
    return { text: isOpen ? tr().opened : tr().closed }
  })

  on('tool.call', { tool: TOOL }, reportProgress)

  on('tool.call', { tool: STEP_TOOL }, reportStep)

  on('turn.start', async ($, e, next) => {
    const started = await next(e)
    const at = await $.clock.now()
    await update($, turnA, t => (!t || t.endedAt !== undefined ? { startedAt: at, actions: 0 } : t))
    return started
  })

  // Claude's own task list, and a plan the person approved, draw the bar too.
  on('tool.call', { tool: 'TodoWrite' }, async ($, e, next) => {
    const r = await next(e)
    const todos = (e as unknown as { todos?: TodoItem[] }).todos
    if (!e.agentId && answered(r) && Array.isArray(todos)) await showList($, todos.filter(t => typeof t?.content === 'string' && t.content.trim()))
    return r
  })

  on('tool.call', { tool: 'TaskCreate' }, async ($, e, next) => {
    const r = await next(e)
    const input = e as unknown as { subject?: string; activeForm?: string }
    const id = (r.result as { task?: { id?: unknown } } | undefined)?.task?.id
    if (!e.agentId && answered(r) && id !== undefined && input.subject) {
      taskItems.set(String(id), { content: input.subject, status: 'pending', activeForm: input.activeForm })
      await showList($, [...taskItems.values()])
    }
    return r
  })

  on('tool.call', { tool: 'TaskUpdate' }, async ($, e, next) => {
    const r = await next(e)
    const input = e as unknown as { taskId?: string; status?: string; subject?: string; activeForm?: string }
    const id = String(input.taskId ?? '')
    const item = taskItems.get(id)
    if (!e.agentId && answered(r) && item) {
      if (input.status === 'deleted') taskItems.delete(id)
      else
        taskItems.set(id, {
          content: input.subject || item.content,
          status: input.status || item.status,
          activeForm: input.activeForm || item.activeForm,
        })
      await showList($, [...taskItems.values()])
    }
    return r
  })

  on('tool.call', { tool: 'ExitPlanMode' }, async ($, e, next) => {
    const r = await next(e)
    const plan = (r.result as { plan?: unknown } | undefined)?.plan
    if (!e.agentId && answered(r) && typeof plan === 'string') await showPlan($, plan)
    return r
  })

  // Safety net: worker launches move the faint layer even if the orchestrator forgets to report.
  on('tool.call', { tool: 'Agent' }, async ($, e, next) => {
    // `savvy-heavy`, or `crabhud:savvy-heavy` as the Agent tool lists the mod's own agents.
    const type = String(e.subagent_type ?? '').replace(/^[^:]*:/, '')
    if (!type.startsWith('savvy-')) return next(e)

    await update($, flow, prev => {
      const base = prev && !prev.isFinished ? { ...blank(), ...prev } : blank()
      return { ...base, running: base.running + 1, phase: base.phase === 'plan' ? 'delegate' : base.phase }
    })
    try {
      return await next(e)
    } finally {
      await update($, flow, prev => (prev ? { ...prev, running: Math.max(0, prev.running - 1) } : prev))
    }
  })

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    if (started.deny !== undefined) return started

    const at = await $.clock.now()
    await update($, agents, list => {
      const round = 1 + list.filter(a => norm(a.description) === norm(e.description) && e.description).length
      const run: AgentRun = {
        id: started.agentId ?? e.tool_use_id,
        agentId: started.agentId,
        type: e.subagentType,
        description: e.description,
        model: started.model,
        status: 'running',
        startedAt: at,
        contextTokens: 0,
        contextMax: windowOf(started.model),
        tokens: 0,
        costUsd: 0,
        steps: 0,
        round,
      }
      return [...list.filter(a => a.id !== run.id), run].slice(-200)
    })
    await update($, now, () => at)
    if (e.subagentType.replace(/^[^:]*:/, '').startsWith('savvy-')) {
      const f = await read($, flow)
      await autoOpen($, f && !f.isFinished ? f.title : 'savvy-flow')
    } else if (!(await $.ui.panes()).some(p => p.id === PANE)) {
      void $.ui.open({ id: PANE, title: tr().pane })
    }
    return started
  })

  // Each model request of a subagent: live context, tokens and cost.
  on('turn.complete', async ($, e, next) => {
    const agentId = e.agentId
    if (agentId) {
      const at = await $.clock.now()
      await update($, agents, list =>
        list.map((a): AgentRun => {
          if (a.agentId !== agentId) return a
          // A run whose steps went unseen still gets the turn's own sum.
          const fallback = a.steps === 0 && e.usage
          return {
            ...a,
            status: e.reason === 'answer' ? 'done' : 'failed',
            endedAt: at,
            ...(fallback && e.usage
              ? {
                  model: e.usage.model || a.model,
                  tokens:
                    e.usage.input_tokens +
                    e.usage.output_tokens +
                    e.usage.cache_read_input_tokens +
                    e.usage.cache_creation_input_tokens,
                  costUsd: costOf(e.usage.model || a.model, e.usage),
                }
              : {}),
          }
        }),
      )
      await update($, now, () => at)
    } else {
      // The main turn ended: nothing is waiting on the person any more.
      await update($, waitingA, () => null)
      const at = await $.clock.now()
      await update($, turnA, t => (t && t.endedAt === undefined ? { ...t, endedAt: at } : t))
      // A plan no task list took over ends with the answer.
      if (e.reason === 'answer') await setFlow($, p => (p && p.source === 'plan' && !p.isFinished ? { ...p, done: p.total, isFinished: true, phase: 'close', step: '' } : p))
      await chime($, 'done')
    }
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const s = tr()
    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui
    const list = await read($, agents)
    const f = await read($, flow)
    const p: Panel = await read($, panel)
    const at = Math.max(await read($, now), ...list.map(a => a.startedAt), 0)

    const running = list.filter(a => a.status === 'running').reverse()
    const finished = list.filter(a => a.status !== 'running').reverse()
    const planned = plannedOf(f, list)
    const t = totals(list, at)
    // The pane's title says "Agents"; inside, only the flow's own name.
    const title = f && !f.isFinished ? f.title : ''

    const toggleCompact = (
      <Button
        key="compact"
        label={p.isCompact ? s.expand : s.collapse}
        plain
        onPress={() => update($, panel, prev => ({ ...prev, isCompact: !prev.isCompact }))}
      />
    )
    const toggleDone = (
      <Button
        key="done"
        label={`${p.isDoneCollapsed ? '▸' : '▾'} ${s.finished} · ${finished.length}`}
        plain
        onPress={() => update($, panel, prev => ({ ...prev, isDoneCollapsed: !prev.isDoneCollapsed }))}
      />
    )
    const isEmpty = list.length === 0 && planned.length === 0
    const summary = `≈${fmtCost(t.cost)}, ${fmtTokens(t.tokens)} ${s.tokensWord}, ${fmtTime(t.time)}`
    const usage = usageLine(await read($, turnA), await read($, spendA), Math.max(at, await $.clock.now()))
    const hasUsage = !!(usage.turn || usage.spend)
    const usageAlt = [usage.turn, usage.spend].filter(Boolean).join(' · ')

    const styles = await read($, styleA)
    if (e.surface === 'desktop' && 'Svg' in ui) {
      const { Svg } = ui
      const W = Math.max(240, Math.min(900, (e.props.bodyColumns || 40) * 8 - 8))
      const section = (key: string, text: string) => (
        <Text key={key} dimColor>
          {text}
        </Text>
      )

      if (p.isCompact) {
        return (
          <Box flexDirection="column" gap={1}>
            <Svg source={compactSvg(W, list, planned, t)} alt={`${list.length} ${s.agentsCount}, ${summary}`} width={W} height={32} />
            {hasUsage && <Svg key="usage" source={usageSvg(W, usage)} alt={usageAlt} width={W} height={22} />}
            {toggleCompact}
          </Box>
        )
      }
      return (
        <Box flexDirection="column">
          <Svg source={headerSvg(W, title, t)} alt={title ? `${title}: ${summary}` : summary} width={W} height={headerHeight(title)} />
          {hasUsage && <Svg key="usage" source={usageSvg(W, usage)} alt={usageAlt} width={W} height={22} />}
          {f && f.groups.length > 0 && (
            <Svg source={stepsSvg(W, f)} alt={stepsOf(f).map((x, i) => `${i < f.done || f.isFinished ? '✓' : i === f.done ? '→' : '○'} ${i + 1}. ${x}`).join(', ')} width={W} height={stepsHeight(f, W)} />
          )}
          {toggleCompact}
          {isEmpty && <Text dimColor>{s.empty}</Text>}
          {running.length > 0 && section('h-run', `${s.running} · ${running.length}`)}
          {running.map(a => (
            <Svg key={a.id} source={agentSvg(W, a, at, styles.desktop)} alt={`${a.description}: ${modelName(a.model)}, ${s.isRunning}`} width={W} height={66} />
          ))}
          {finished.length > 0 && toggleDone}
          {!p.isDoneCollapsed &&
            finished.map(a => (
              <Svg key={a.id} source={agentSvg(W, a, at, styles.desktop)} alt={`${a.description}: ${modelName(a.model)}, ${s.isFinished}`} width={W} height={66} />
            ))}
          {planned.length > 0 && section('h-plan', `${s.planned} · ${planned.length}`)}
          {planned.map(pl => (
            <Svg key={`plan-${pl.n}`} source={plannedSvg(W, pl)} alt={`${pl.n}. ${pl.title}: ${s.isPlanned}`} width={W} height={46} />
          ))}
        </Box>
      )
    }

    // Terminal: the same content in text rows.
    const cols = Math.max(24, e.props.bodyColumns || 40)
    const barW = Math.max(6, Math.min(20, cols - 34))
    const row = (a: AgentRun) => {
      const tier = tierOf(a.type)
      const color = colorOf(costumeOf(a.type))
      const ctx = ctxOf(a)
      const progress = progressOf(a)
      const model = a.effort ? `${modelName(a.model)} · ${a.effort}` : modelName(a.model)
      const steps = a.stepTotal ? `${a.stepDone ?? 0}/${a.stepTotal}${a.stepNote ? ' ' + a.stepNote : ''} · ` : ''
      return (
        <Box key={a.id} flexDirection="column" marginBottom={1}>
          <Box flexDirection="row" gap={1}>
            <Text color={color}>▣</Text>
            <Text bold wrap="truncate-end">
              {a.description || a.type}
            </Text>
            <Text color={a.status === 'failed' ? 'red' : a.status === 'done' ? 'green' : color}>{STATUS_GLYPH[a.status]}</Text>
          </Box>
          <Text dimColor wrap="truncate-end">
            {'  '}
            {tier === 'other' ? a.type : tier} · {model}
            {a.round > 1 ? ` · ${s.round} ${a.round}` : ''}
          </Text>
          <Text wrap="truncate-end">
            {'  '}
            {cellTexts(Text, barCells(styles.terminal, progress === null ? ctx : progress * 100, barW, () => (progress === null ? GREY : color), 0, false))}
            <Text dimColor>
              {' '}
              {steps}ctx {ctx}% · {fmtTokens(a.contextTokens)} ≈{fmtCost(a.costUsd)} {fmtTime(elapsed(a, at))}
            </Text>
          </Text>
        </Box>
      )
    }

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" justifyContent="space-between">
          <Text bold wrap="truncate-end">
            {title}
          </Text>
          {toggleCompact}
        </Box>
        <Text dimColor>
          ≈{fmtCost(t.cost)} · {fmtTokens(t.tokens)} {s.tokensWord} · {fmtTime(t.time)}
        </Text>
        {usage.turn ? <Text dimColor wrap="truncate-end">{usage.turn}</Text> : null}
        {usage.spend ? <Text dimColor wrap="truncate-end">{usage.spend}</Text> : null}
        {p.isCompact ? (
          <Text wrap="truncate-end">
            {[...running, ...finished].map(a => (
              <Text key={a.id} color={colorOf(costumeOf(a.type))}>
                {STATUS_GLYPH[a.status]}{' '}
              </Text>
            ))}
            {planned.map(pl => (
              <Text key={`plan-${pl.n}`} dimColor>
                ◷{' '}
              </Text>
            ))}
          </Text>
        ) : (
          <Box flexDirection="column" marginTop={1}>
            {isEmpty && <Text dimColor>{s.empty}</Text>}
            {running.length > 0 && <Text dimColor>{s.running} · {running.length}</Text>}
            {running.map(row)}
            {finished.length > 0 && toggleDone}
            {!p.isDoneCollapsed && finished.map(row)}
            {planned.length > 0 && <Text dimColor>{s.planned} · {planned.length}</Text>}
            {planned.map(pl => {
              const tier = pl.tier in TIER_COLOR ? pl.tier : 'other'
              return (
                <Box key={`plan-${pl.n}`} flexDirection="column" marginBottom={1}>
                  <Text dimColor wrap="truncate-end">
                    <Text color={colorOf(tier)}>▢</Text> {pl.n}. {pl.title} ◷
                  </Text>
                  <Text dimColor wrap="truncate-end">
                    {'  '}
                    {tier} · {TIER_MODEL[tier] ?? ''}
                    {pl.after.length ? ` · ${s.after} ${pl.after.join(', ')}` : ''}
                  </Text>
                </Box>
              )
            })}
          </Box>
        )}
      </Box>
    )
  })

  // A call the engine puts to the person: once the ask has stood a moment
  // (a mode that settles it at once never shows a prompt), the row turns amber.
  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    const id = e.tool_use_id
    if (verdict?.decision === 'ask' && id) {
      const w: Waiting = { kind: 'permission', tool: e.tool, detail: targetOf((e.input ?? {}) as Record<string, unknown>), id }
      $.clock.after(ASK_DELAY_MS, () => {
        if (inFlight.has(id)) void startWaiting($, w)
      })
    }
    return verdict
  })

  // Every call in flight (for the ask above), Claude's own question (amber
  // while it waits for the answer), and the main agent's tool: what the crab
  // in the corner acts out.
  on('tool.call', async ($, e, next) => {
    const id = e.tool_use_id
    if (id) inFlight.add(id)
    try {
      if (e.tool === 'AskUserQuestion' && id) {
        const qs = (e as unknown as { questions?: { question?: unknown }[] }).questions
        const question = typeof qs?.[0]?.question === 'string' ? qs[0].question : ''
        await startWaiting($, { kind: 'answer', tool: e.tool, detail: question, id })
      }
      if (e.agentId === undefined && e.tool !== TOOL && e.tool !== STEP_TOOL)
        await update($, turnA, t => (t && t.endedAt === undefined ? { ...t, actions: t.actions + 1 } : t))
      if (e.agentId !== undefined || e.tool === 'Agent' || e.tool === TOOL || e.tool === STEP_TOOL) return await next(e)
      await update($, activity, () => ({ id, kind: kindOf(e.tool), target: targetOf(e as unknown as Record<string, unknown>) }))
      try {
        return await next(e)
      } finally {
        await update($, activity, prev => (prev?.id === id ? null : prev))
      }
    } finally {
      if (id) {
        inFlight.delete(id)
        await update($, waitingA, w => (w?.id === id ? null : w))
      }
    }
  })

  // Always on, above the other mods in the band: the flow's bar when one runs,
  // else the crab and what Claude is doing.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const f = await read($, flow)

    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui
    // The band is shared: the bar sits on top, a hairline under it, and what the
    // other mods draw stays below.
    const theirs = await next(e)
    // About 8 CSS px per reported column. No floor above the slot: a row wider than it would wrap.
    const slot = (e.props.bodyColumns || 100) * 8
    const list = await read($, agents)
    const running = list.filter(a => a.status === 'running').length
    const act = await read($, activity)
    const mood = moodOf(e.props.isWorking, running, act)
    const status = moodText(mood, running, act)
    const crew = list.length + plannedOf(f, list).length
    // Opens or closes the agents pane; says how many subagents this session ran.
    const crewButton = crew ? (
      <Button key="savvy-agents" label={tr().agentsN(crew)} plain onPress={() => void togglePane($)} />
    ) : null
    // The drawing gets the slot minus the buttons beside it (the count, the dismiss) and their gaps.
    const buttons = (crew ? Math.round(textWidth(tr().agentsN(crew), 13)) + 36 : 0) + (f ? 40 : 0)
    const width = Math.max(180, Math.min(1600, slot - Math.max(24, buttons) - 16))
    // Drawings everywhere but the terminal, which draws text (its table has no Svg).
    const vector = e.surface !== 'terminal' && 'Svg' in ui
    const divider =
      vector ? (
        <ui.Svg source={hairline(width)} alt="—" width={width} height={13} />
      ) : (
        <Text dimColor>{'─'.repeat(Math.max(4, e.props.bodyColumns || 40))}</Text>
      )
    const above = (bar: RenderElement) => (
      <Box flexDirection="column">
        {bar}
        {divider}
        {theirs}
      </Box>
    )

    // Claude waiting on the person: an amber row above the rest, while it lasts.
    const waiting = await read($, waitingA)
    const waitText = waiting
      ? [waiting.kind === 'answer' ? tr().waitAnswer : tr().waitPermission, waiting.kind === 'permission' ? [waiting.tool, waiting.detail].filter(Boolean).join(': ') : waiting.detail]
          .filter(Boolean)
          .join(' · ')
      : ''
    const waitRow = !waiting ? null : vector ? (
      <ui.Svg key="savvy-wait" source={waitSvg(width, waitText)} alt={waitText} width={width} height={H} />
    ) : (
      <Text key="savvy-wait" color={WAIT} bold wrap="truncate-end">
        ! {waitText}
      </Text>
    )
    const t = await $.clock.now()
    if (scene.mood !== mood) scene = { mood, at: t }
    // The turn so far, beside the walking crab: how many tools, how long. Reading
    // `now` redraws the row as the clock ticks.
    await read($, now)
    const turn = await read($, turnA)
    const note = e.props.isWorking && turn && turn.endedAt === undefined ? `${tr().actionsN(turn.actions)} · ${fmtSpan(t - turn.startedAt)}` : ''

    if (f === null) {
      if (waitRow) return above(waitRow)
      if (vector) {
        const { Svg } = ui
        // At work the crab walks the free part of the row; asleep it keeps still.
        const art = mood === 'sleep' ? moodSvg(width, mood, status) : walkSvg(width, mood, status, t - scene.at, note)
        return above(
          <Box flexDirection="row" alignItems="center" gap={1}>
            <Svg source={art} alt={status} width={width} height={H} />
            {crewButton}
          </Box>,
        )
      }
      return above(
        <Box flexDirection="row" gap={1}>
          <Text color={CLAY}>▣</Text>
          <Text wrap="truncate-end" dimColor={mood === 'sleep'}>
            {status}
          </Text>
          {note ? <Text dimColor>{note}</Text> : null}
          {crewButton}
        </Box>,
      )
    }

    const percent = `${Math.round(ratio(f) * 100)}%`
    const dismiss = (
      <Button
        key="savvy-dismiss"
        label="✕"
        plain
        role="dismiss"
        onPress={async () => {
          await update($, flow, () => null)
          if ((f.source ?? 'tool') === 'tool') await keepBar($, null)
        }}
      />
    )

    // With a flow on, the amber row sits above the bar.
    const withWait = (bar: RenderElement) =>
      waitRow ? (
        <Box flexDirection="column">
          {waitRow}
          {bar}
        </Box>
      ) : (
        bar
      )

    if (vector) {
      const { Svg } = ui
      // A step just taken: the tag glides from where it was.
      const glide = f.moved && t - f.moved.at < GLIDE_MS ? { p: f.moved.from, age: t - f.moved.at } : undefined
      // Just reached 100%: the crab's celebration.
      const party = f.isFinished && f.doneAt !== undefined && t - f.doneAt < PARTY_MS ? t - f.doneAt : undefined
      return above(withWait(
        <Box flexDirection="row" alignItems="center" gap={1}>
          <Svg source={rowSvg(f, width, mood, (await read($, styleA)).desktop, glide, party)} alt={`${f.title}: ${label(f)}, ${percent} · ${status}`} width={width} height={rowHeight(f)} />
          {crewButton}
          {dismiss}
        </Box>,
      ))
    }

    const cols = e.props.bodyColumns
    const titleW = Math.max(8, Math.min(30, f.title.length + 2, Math.floor(cols / 3)))
    const barW = Math.max(6, Math.min(40, cols - titleW - 32))
    return above(withWait(
      <Box flexDirection="row" gap={2}>
        <Box width={titleW} flexShrink={0}>
          <Text color={f.isFinished ? DONE : ACCENT}>● </Text>
          <Text wrap="truncate-end">{f.title}</Text>
        </Box>
        <Box flexDirection="row" flexShrink={0}>
          {cellTexts(Text, barText(f, barW, (await read($, styleA)).terminal))}
        </Box>
        <Text bold>{label(f)}</Text>
        <Text dimColor>{percent}</Text>
        <Text color={CLAY}>▣</Text>
        {crewButton}
        {dismiss}
      </Box>,
    ))
  })
}

// ===========================================================================
// HUD: model, effort, context, 5-hour and 7-day limits, cost
// ===========================================================================

// Per chat: its context and cost, model and effort. Global: the account's
// limits, shared between chats through a small file every HUD reads.
const chatA = atom({ plugin: 'crabhud', key: 'chat' } as const, null)
const limitsA = atom({ plugin: 'crabhud', key: 'limits' } as const, null)
const modelA = atom({ plugin: 'crabhud', key: 'model' } as const, '')
const effortA = atom({ plugin: 'crabhud', key: 'effort' } as const, null)
const ultraA = atom({ plugin: 'crabhud', key: 'ultracode' } as const, false)
const expandedA = atom({ plugin: 'crabhud', key: 'expanded' } as const, false)
const hiddenA = atom({ plugin: 'crabhud', key: 'hidden' } as const, false)
const alertedA = atom({ plugin: 'crabhud', key: 'alerted' } as const, [])
// The HUD's language; null until the person picks one on the first run.
const langA = atom({ plugin: 'crabhud', key: 'language' } as const, null)
// The bars' look, per surface (/crabhud style).
const DEFAULT_STYLES: HudStyles = { terminal: 'classic', desktop: 'pixel' }
const styleA = atom({ plugin: 'crabhud', key: 'style' } as const, DEFAULT_STYLES)
// Every 30 s: the app's HUD reads it, so its reset countdowns stay current.
const tickA = atom({ plugin: 'crabhud', key: 'tick' } as const, 0)
const STYLE_PANE = 'crabhud-style'

const LANGS: readonly HudLang[] = ['en', 'pt-BR']
